package tri_lion.health.service.expert;
import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tri_lion.health.exception.ApiException;import tri_lion.health.security.AuthenticatedUser;
@Service public class ExpansionService{private final JdbcTemplate db;private final AuthenticatedUser auth;private final ObjectMapper json;public ExpansionService(JdbcTemplate d,AuthenticatedUser a,ObjectMapper j){db=d;auth=a;json=j;}@Transactional public Long apply(String type,List<String>specialties,String intro){Long u=auth.active().getId();if(db.queryForObject("select count(*) from experts where user_id=?",Integer.class,u)>0)throw ApiException.conflict("이미 전문가 인증을 신청했습니다.");db.update("insert into experts(user_id,specialty,qualification_info,introduction,verification_status,applied_at) values(?,?,?,?,?,?)",u,String.join(",",specialties),"certificate files stored privately",intro,"PENDING_REVIEW",Instant.now());return u;}@Transactional public Long content(Map<String,Object>q){Long u=auth.active().getId();String status=db.query("select verification_status from experts where user_id=?",rs->rs.next()?rs.getString(1):null,u);if(!"APPROVED".equals(status))throw ApiException.forbidden("인증된 전문가만 콘텐츠를 등록할 수 있습니다.");Number key=new org.springframework.jdbc.support.GeneratedKeyHolder().getKey();org.springframework.jdbc.support.KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{var ps=c.prepareStatement("insert into market_items(name,item_type,price,provider_name,status) values(?,?,?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);ps.setString(1,String.valueOf(q.get("title")));ps.setString(2,"CURRICULUM");ps.setLong(3,Long.parseLong(String.valueOf(q.getOrDefault("price",0))));ps.setString(4,"TRI_LION");ps.setString(5,"DRAFT");return ps;},kh);Long id=Objects.requireNonNull(kh.getKey()).longValue();db.update("insert into curricula(market_item_id,expert_id,category,difficulty,duration_days,description) values(?,?,?,?,?,?)",id,u,q.get("category"),q.get("difficulty"),Integer.parseInt(String.valueOf(q.getOrDefault("durationWeeks",1)))*7,q.get("description"));return id;}public List<Map<String,Object>>contents(){return db.queryForList("select m.market_item_id id,m.name,m.price,m.image_url thumbnailUrl,c.category,c.difficulty,u.name expertName from market_items m join curricula c on c.market_item_id=m.market_item_id join users u on u.user_id=c.expert_id where m.status in ('ACTIVE','PUBLISHED')");}public Map<String,Object>content(Long id){return db.queryForMap("select m.market_item_id id,m.name,m.price,m.image_url thumbnailUrl,c.category,c.difficulty,c.description,u.name expertName from market_items m join curricula c on c.market_item_id=m.market_item_id join users u on u.user_id=c.expert_id where m.market_item_id=?",id);}@Transactional public Long enroll(Long id,String access,boolean personalized){Long u=auth.active().getId();org.springframework.jdbc.support.KeyHolder kh=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{var ps=c.prepareStatement("insert into enrollments(user_id,content_id,access_type,personalized,progress_rate,status,started_at) values(?,?,?,?,0,'ACTIVE',?)",java.sql.Statement.RETURN_GENERATED_KEYS);ps.setLong(1,u);ps.setLong(2,id);ps.setString(3,access);ps.setBoolean(4,personalized);ps.setObject(5,LocalDate.now());return ps;},kh);return Objects.requireNonNull(kh.getKey()).longValue();}public List<Map<String,Object>>products(){auth.active();return db.queryForList("select provider_name partner,market_item_id externalProductId,name,price,image_url imageUrl,purchase_url purchaseUrl from market_items where item_type='MEAL' and status='ACTIVE'");}public Map<String,Object>cart(String partner,List<Map<String,Object>>items){auth.active();return Map.of("cartId",UUID.randomUUID().toString(),"partner",partner,"checkoutUrl","https://partner.example.com/deep-link","items",items,"expiresAt",Instant.now().plusSeconds(1800));}}
